const { parentPort } = require('worker_threads');
const https = require('https');
const http = require('http');
const { URL } = require('url');

// \u6BCF\u4E2A worker \u6301\u6709 keepAlive agent\uFF0C\u8FDE\u63A5\u590D\u7528\uFF1ATLS \u63E1\u624B\u53EA\u4ED8\u4E00\u6B21\uFF0CTCP \u62E5\u585E\u7A97\u53E3\u6301\u7EED\u6253\u5F00
const agentCache = {};
function getAgent(lib, hostname) {
    const key = (lib === https ? 's:' : 'h:') + hostname;
    if (!agentCache[key]) {
        agentCache[key] = new lib.Agent({
            keepAlive: true,
            keepAliveMsecs: 30000,
            maxSockets: 2,
            scheduling: 'lifo',
        });
    }
    return agentCache[key];
}

// \u91CD\u5B9A\u5411\u540E\u7F13\u5B58\u6700\u7EC8 CDN URL\uFF0C\u540C worker \u540E\u7EED chunk \u514D 302 \u5F80\u8FD4
let finalUrl = null;

function downloadRange(urlStr, start, end, timeoutMs, headers, redirectCount) {
    redirectCount = redirectCount || 0;
    if (redirectCount > 5) return Promise.reject(new Error('too many redirects'));
    // \u975E\u91CD\u5B9A\u5411\u8BF7\u6C42\u4F18\u5148\u7528\u7F13\u5B58\u7684\u6700\u7EC8 CDN \u5730\u5740
    if (finalUrl && redirectCount === 0) urlStr = finalUrl;
    return new Promise((resolve, reject) => {
        const u = new URL(urlStr);
        const lib = u.protocol === 'https:' ? https : http;
        const reqHeaders = Object.assign({ Range: 'bytes=' + start + '-' + end }, headers || {});
        const opt = {
            hostname: u.hostname,
            port: u.port,
            path: u.pathname + u.search,
            headers: reqHeaders,
            rejectUnauthorized: false,
            agent: getAgent(lib, u.hostname),
        };
        const r = lib.request(opt, (res) => {
            // 302/301/307/308 \u91CD\u5B9A\u5411\uFF1A\u8DDF\u968F location\uFF0C\u590D\u7528\u540C\u4E00 Range \u5934
            if (res.statusCode === 301 || res.statusCode === 302 || res.statusCode === 307 || res.statusCode === 308) {
                const loc = res.headers.location;
                res.resume();
                if (!loc) { reject(new Error('redirect without location')); return; }
                finalUrl = loc; // \u7F13\u5B58\u771F\u5B9E CDN \u5730\u5740
                downloadRange(loc, start, end, timeoutMs, headers, redirectCount + 1).then(resolve, reject);
                return;
            }
            if (res.statusCode !== 200 && res.statusCode !== 206) {
                res.resume();
                reject(new Error('HTTP ' + res.statusCode));
                return;
            }
            const chunks = [];
            res.on('data', (c) => chunks.push(c));
            res.on('end', () => resolve(Buffer.concat(chunks)));
            res.on('error', reject);
        });
        r.on('error', reject);
        r.setTimeout(timeoutMs, () => { r.destroy(new Error('timeout')); });
        r.end();
    });
}

parentPort.on('message', async (msg) => {
    const { taskId, url, start, end, timeout, headers, finalUrl: cachedUrl } = msg;
    // \u4F18\u53163: \u4E3B\u7EBF\u7A0B\u4F20\u5165\u7684\u5171\u4EAB\u76F4\u5740\u4F18\u5148\uFF08\u8DE8\u8BF7\u6C42/\u8DE8 worker \u590D\u7528\uFF09
    if (cachedUrl) finalUrl = cachedUrl;
    try {
        const buf = await downloadRange(url, start, end, timeout, headers);
        // Transferable: \u96F6\u62F7\u8D1D\u4F20\u56DE\u4E3B\u7EBF\u7A0B\uFF1BdiscoveredUrl \u4E0A\u62A5\u672C worker \u5B9E\u9645\u4F7F\u7528\u7684\u76F4\u5740
        parentPort.postMessage({ taskId, ok: true, buf: buf.buffer, len: buf.length, discoveredUrl: finalUrl }, [buf.buffer]);
    } catch (e) {
        parentPort.postMessage({ taskId, ok: false, error: e.message, discoveredUrl: finalUrl });
    }
});
